local TokenMaker = {}
local PRODUCTS = {
    game_token = { name = "Igralni žeton", metalCost = 1, time = 1, cost = 3, quantity = 20, description = "Žetoni za igre." },
    trade_token = { name = "Trgovski žeton", metalCost = 2, time = 2, cost = 10, quantity = 10, description = "Za trgovino." },
    pilgrimage_badge = { name = "Romarski znak", metalCost = 1, time = 2, cost = 15, faith = 3, happiness = 1, description = "Znaki za romarje." },
    commemorative_medal = { name = "Spominska medalja", metalCost = 3, time = 5, cost = 50, prestige = 5, description = "Za pomembne dogodke." },
    silver_medal = { name = "Srebrna medalja", silverCost = 2, time = 7, cost = 150, prestige = 10, happiness = 3, description = "Srebrna spominska medalja." },
    royal_commemorative = { name = "Kraljevski spomenik", goldCost = 3, jewelCost = 1, time = 14, cost = 500, prestige = 25, happiness = 8, description = "Zlata medalja za kraljevske dogodke." },
}
local BUILDINGS = {
    workshop = { name = "Žetonska delavnica", cost = { gold = 200, wood = 100, iron = 30 }, upkeep = 5, qualityBonus = 5 },
    minting_press = { name = "Kovinska stiska", cost = { gold = 800, wood = 200, stone = 200, iron = 100 }, upkeep = 20, qualityBonus = 15 },
    engraving_shop = { name = "Graverska delavnica", cost = { gold = 1500, wood = 200, stone = 300, iron = 50 }, upkeep = 30, qualityBonus = 25 },
    royal_mint = { name = "Kraljevska kovnica", cost = { gold = 4000, wood = 400, stone = 800, iron = 200, gold = 50 }, upkeep = 80, qualityBonus = 40, prestigeBonus = 20 },
}
TokenMaker.metalStock = 15; TokenMaker.silverStock = 5; TokenMaker.goldStock = 3; TokenMaker.jewelStock = 2
TokenMaker.productStock = {}; TokenMaker.buildings = {}; TokenMaker.maker = nil; TokenMaker.activeMaking = {}; TokenMaker.totalProducts = 0; TokenMaker.dayTimer = 0
function TokenMaker.init() TokenMaker.metalStock=15; TokenMaker.silverStock=5; TokenMaker.goldStock=3; TokenMaker.jewelStock=2; TokenMaker.productStock={}; TokenMaker.buildings={}; TokenMaker.maker=nil; TokenMaker.activeMaking={}; TokenMaker.totalProducts=0; TokenMaker.dayTimer=0; print("[TokenMaker] Royal Token & Medal Maker System initialized (6 products, 4 buildings)") end
function TokenMaker.hireMaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TokenMaker.maker={name=n or ("Žetonar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žetonar najet: %s (spretnost: %d)",TokenMaker.maker.name,s),"success") end; return true end
function TokenMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TokenMaker.build(id) local ok,e=TokenMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TokenMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TokenMaker.getQualityBonus() local b=0; for _,bd in ipairs(TokenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TokenMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.metalCost and TokenMaker.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.silverCost and TokenMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TokenMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TokenMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if #TokenMaker.buildings==0 then return false,"Potrebna delavnica" end; if not TokenMaker.maker then return false,"Potreben žetonar" end; return true end
function TokenMaker.make(pt) local ok,e=TokenMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.metalCost then TokenMaker.metalStock=TokenMaker.metalStock-d.metalCost end; if d.silverCost then TokenMaker.silverStock=TokenMaker.silverStock-d.silverCost end; if d.goldCost then TokenMaker.goldStock=TokenMaker.goldStock-d.goldCost end; if d.jewelCost then TokenMaker.jewelStock=TokenMaker.jewelStock-d.jewelCost end; local t=d.time; if TokenMaker.maker then t=math.max(1,t-math.floor(TokenMaker.maker.skill/12)) end; table.insert(TokenMaker.activeMaking,{id="token_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,quantity=d.quantity or 1,prestige=d.prestige or 0,happiness=d.happiness or 0,faith=d.faith or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %s (%d dni)",d.name,t),"info") end; return true end
function TokenMaker.completeMaking(m) local q=1.0+(TokenMaker.getQualityBonus()/100); if TokenMaker.maker then q=q+(TokenMaker.maker.skill/200) end; q=math.min(2.0,q); TokenMaker.productStock[m.productType]=(TokenMaker.productStock[m.productType] or 0)+m.quantity; TokenMaker.totalProducts=TokenMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.faith>0 and _G.Religion then pcall(_G.Religion.addFaith,m.faith*m.quantity) end; if TokenMaker.maker then TokenMaker.maker.itemsMade=TokenMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then TokenMaker.maker.skill=math.min(100,TokenMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žetoni izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function TokenMaker.update(dt) if not _G.state then return end; TokenMaker.dayTimer=TokenMaker.dayTimer+dt; if TokenMaker.dayTimer>=30 then TokenMaker.dayTimer=0; for i=#TokenMaker.activeMaking,1,-1 do local m=TokenMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TokenMaker.completeMaking(m); table.remove(TokenMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TokenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TokenMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TokenMaker.getStats() return {metalStock=TokenMaker.metalStock,silverStock=TokenMaker.silverStock,goldStock=TokenMaker.goldStock,jewelStock=TokenMaker.jewelStock,productStock=TokenMaker.productStock,numBuildings=#TokenMaker.buildings,hasMaker=TokenMaker.maker~=nil,makerName=TokenMaker.maker and TokenMaker.maker.name or "—",makerSkill=TokenMaker.maker and TokenMaker.maker.skill or 0,activeMaking=#TokenMaker.activeMaking,totalProducts=TokenMaker.totalProducts} end
return TokenMaker
